import {Trace} from './trace.mjs';
export function treeLevel(){const source=`#include <stdio.h>\ntypedef struct s_tree\n{\n    int data;\n    struct s_tree *left;\n    struct s_tree *right;\n} t_tree;\nint main(void)\n{\n    t_tree left = {1, NULL, NULL};\n    t_tree right = {3, NULL, NULL};\n    t_tree root = {2, &left, &right};\n    t_tree *queue[3];\n    int front = 0;\n    int back = 1;\n    queue[0] = &root;\n    while (front < back)\n    {\n        t_tree *cur = queue[front];\n        front++;\n        printf("%d ", cur->data);\n        if (cur->left != NULL)\n        {\n            queue[back] = cur->left;\n            back++;\n        }\n        if (cur->right != NULL)\n        {\n            queue[back] = cur->right;\n            back++;\n        }\n    }\n    putchar('\n');\n    return (0);\n}`.replace("putchar('\n');","putchar('\\n');");const b=new Trace('tree-level','Tree · breadth-first visitation','A queue visits all nodes at one level before moving to the next level.',source),nodes={left:{data:1,left:null,right:null,address:'0x1000'},right:{data:3,left:null,right:null,address:'0x1100'},root:{data:2,left:'left',right:'right',address:'0x1200'}};for(const [id,loc]of [['left',0x1000],['right',0x1100],['root',0x1200]])b.step(`t_tree ${id} = {${id==='root'?'2, &left, &right':nodes[id].data+', NULL, NULL'}};`,'Create '+id,'Initialize the node data and child links.','This three-node tree has two levels when levels are counted in nodes. The source does not specify a nodes-versus-edges convention for its height exercise.','data and links → node',()=>{b.cell(id,id,'t_tree',loc,JSON.stringify(nodes[id]));if(!b.state.world)b.state.world={kind:'tree',root:id,nodes:[]};b.state.world.nodes.push({id,...nodes[id]});if(id==='root')b.state.world.root='root';});b.step('t_tree *queue[3];','Reserve a pointer queue','Create three uninitialized pointer slots.','This small queue has capacity for exactly the three nodes. A general tree requires capacity management.','pointer slots → queue',()=>{for(let i=0;i<3;i++)b.cell('q'+i,`queue[${i}]`,'t_tree *',0x2000+i*8,undefined);});for(const [id,val,loc]of [['front',0,0x2100],['back',1,0x2104]])b.step(`int ${id} = ${val};`,'Initialize '+id,`Store ${val} in ${id}.`,'front selects the next queued item; back selects the next insertion position.','value → '+id,()=>b.cell(id,id,'int',loc,val));b.step('queue[0] = &root;','Enqueue the root','Store root’s address in the first queue slot.','No node data is copied into the queue.','&root → queue[0]',()=>b.ptr('q0','queue[0]','t_tree *',0x2000,'root'));let back=1;for(const [i,id]of ['root','left','right'].entries()){b.step('while (front < back)','Check for queued work',`${i} < ${back} is true.`,'A nonempty queue means at least one node is waiting.','front < back → true',()=>{},['front','back']);b.step('t_tree *cur = queue[front];','Dequeue the next node','Copy '+id+'’s address into cur.','cur is an automatic object of this loop-body block. It is recreated on each iteration.','queued address → cur',()=>b.ptr('cur','cur','t_tree *',0x2110,id),['q'+i],[id]);b.step('front++;','Consume this queue slot','Increase front to '+(i+1)+'.','The queue slot is still initialized, but it is no longer pending work.','front + 1 → front',()=>b.set('front',i+1));b.step('printf("%d ", cur->data);','Visit the dequeued node','Print '+nodes[id].data+'.','The root prints first, then its left and right children.','node data → terminal',()=>b.state.output+=nodes[id].data+' ',['cur',id],[id]);for(const side of ['left','right']){const child=nodes[id][side];b.step(`if (cur->${side} != NULL)`,'Check the '+side+' child',child?'This child exists and must be queued.':'This link is NULL; skip enqueueing.','Only real children enter the queue.','child != NULL → '+!!child,()=>{},['cur',id]);if(child){const slot=back;b.step(`queue[back] = cur->${side};`,'Enqueue the child','Copy '+child+'’s address into queue['+slot+'].','The child will be visited after the nodes already waiting.','child address → queue slot',()=>b.ptr('q'+slot,`queue[${slot}]`,'t_tree *',0x2000+slot*8,child),['cur',id]);back++;b.step('back++;','Advance the insertion position','Increase back to '+back+'.','This tracks the number of queued entries.','back + 1 → back',()=>b.set('back',back));}}
  b.step(b.code.findIndex(l=>l==='    }')+1,'End this loop-body scope','The automatic cur object leaves this iteration’s block.','The next iteration creates a new cur. Node objects and queue slots remain alive.','loop-body local lifetime ends',()=>delete b.state.cells.cur);
 }b.step('while (front < back)','Finish when the queue is empty','3 < 3 is false.','All three nodes have been visited in breadth-first order: 2, 1, 3.','queue empty → stop',()=>{},['front','back']);return b.finish("putchar('\\n');",'\n');}
